dataprocessscript.script:
import java.util.Properties;
import java.io.InputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.BufferedInputStream;
import java.security.MessageDigest;

for (int i = 0; i < dataContext.getDataCount(); i++) {
    InputStream doc = dataContext.getStream(i);
    Properties props = dataContext.getProperties(i);

    String path = props.getProperty("document.dynamic.userdefined.DDP_P01_STREAM_FILE", "");
    String expectedSha = props.getProperty("document.dynamic.userdefined.DDP_P01_EXPECTED_SHA256", "");
    String expectedBytes = props.getProperty("document.dynamic.userdefined.DDP_P01_EXPECTED_BYTES", "");
    File file = new File(path);

    if (!file.isFile()) {
        props.setProperty("document.dynamic.userdefined.DDP_P01_INTEGRITY_STATUS", "FAILED");
        props.setProperty("document.dynamic.userdefined.DDP_P01_FAILURE_REASON", "SOURCE_NOT_FOUND: " + path);
        dataContext.storeStream(doc, props);
        continue;
    }

    MessageDigest digest = MessageDigest.getInstance("SHA-256");
    byte[] buffer = new byte[65536];
    long total = 0L;
    BufferedInputStream input = new BufferedInputStream(new FileInputStream(file), 65536);
    try {
        int n;
        while ((n = input.read(buffer)) != -1) {
            digest.update(buffer, 0, n);
            total += n;
        }
    }
    finally {
        input.close();
    }

    StringBuilder hex = new StringBuilder();
    byte[] hash = digest.digest();
    for (int j = 0; j < hash.length; j++) {
        hex.append(String.format("%02x", hash[j] & 0xff));
    }

    String actualSha = hex.toString();
    boolean hashOk = expectedSha == null || expectedSha.trim().length() == 0 || actualSha.equalsIgnoreCase(expectedSha.trim());
    boolean bytesOk = true;
    if (expectedBytes != null && expectedBytes.trim().length() > 0) {
        bytesOk = total == Long.parseLong(expectedBytes.trim());
    }

    props.setProperty("document.dynamic.userdefined.DDP_P01_ACTUAL_BYTES", String.valueOf(total));
    props.setProperty("document.dynamic.userdefined.DDP_P01_ACTUAL_SHA256", actualSha);
    props.setProperty("document.dynamic.userdefined.DDP_P01_MAX_HEAP_BYTES", String.valueOf(Runtime.getRuntime().maxMemory()));
    props.setProperty("document.dynamic.userdefined.DDP_P01_INTEGRITY_STATUS", (hashOk && bytesOk) ? "PASSED" : "FAILED");

    if (!hashOk) props.setProperty("document.dynamic.userdefined.DDP_P01_FAILURE_REASON", "SHA256_MISMATCH");
    else if (!bytesOk) props.setProperty("document.dynamic.userdefined.DDP_P01_FAILURE_REASON", "BYTE_COUNT_MISMATCH");
    else props.setProperty("document.dynamic.userdefined.DDP_P01_FAILURE_REASON", "");

    dataContext.storeStream(doc, props);
}
